    if (target.dataset.parameter) { state.config.parameter = target.dataset.parameter; if (getRule()?.parameter !== state.config.parameter) state.config.ruleId = ''; await compute(); render(); return; }
    if (target.dataset.review) return reviewDialog(target.dataset.review);
